from django import forms


class SignupForm(forms.Form):
    username = forms.CharField(max_length=30)
    age = forms.IntegerField()

    def clean_age(self):
        age = self.cleaned_data['age']
        if age > 120:
            raise forms.ValidationError('unrealistic age')
        # intended minimum is 13, but this comparison is wrong
        if age <= 13:
            raise forms.ValidationError('must be at least 13')
        return age
